/* Actual local lesson edits, always restored. The injected 503 checks failure handling only. */
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');const assert=require('node:assert/strict'),fs=require('node:fs/promises');const base=process.env.SAWTI_TEST_BASE||'http://127.0.0.1:3002';const clean=s=>s.replace(/[\u064b-\u065f\u0670\u0640]/g,'');
async function click(p,text){for(const b of await p.getByRole('button').all())if(await b.isVisible()&&clean(await b.innerText()).includes(text)){await b.click();return}throw Error('Missing '+text)}
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true});const page=await browser.newPage();await page.goto(base+'/teacher');await page.getByLabel('رَمْزُ الدُّخُولِ:').fill('audit-teacher-local');await page.getByRole('button',{name:'دُخُولٌ',exact:true}).click();await page.getByRole('button',{name:/نَظْرَةٌ عَامَّةٌ/}).waitFor();await click(page,'الدروس');
const token=await page.evaluate(()=>sessionStorage.getItem('sawti_teacher_token'));const headers={Authorization:'Bearer '+token};const out=[];
for(const type of ['speaking','writing']){const url=base+'/api/lessons/'+type;const original=(await(await page.request.get(url)).json())[0];try{
 if(type==='writing')await click(page,'الكتابة');await page.getByRole('button',{name:/تَعْدِيلٌ/}).first().click();await page.getByRole('dialog').waitFor();const field=type==='speaking'?'وصف الدرس':'الأفكار المساعدة (افصل بينها بفاصلة عربية ،)';const value=type==='speaking'?original.desc+' — اختبار حفظ المظهر':original.hints.join('، ')+ '، مراجعة التصميم';await page.getByLabel(field,{exact:true}).fill(value);const response=page.waitForResponse(r=>r.url().includes('/lessons/'+type+'/')&&r.request().method()==='PUT');await page.getByRole('button',{name:'حفظ التغييرات',exact:true}).click();assert.equal((await response).status(),200);await page.getByRole('dialog').waitFor({state:'hidden'});const saved=(await(await page.request.get(url)).json()).find(r=>r.id===original.id);if(type==='speaking')assert.equal(saved.desc,value);else assert(saved.hints.includes('مراجعة التصميم'));out.push({case:type+' edit → API → real database roundtrip',status:'PASS'});
}finally{const response=await page.request.put(url+'/'+encodeURIComponent(original.id),{headers,data:original});assert.equal(response.status(),200)}}
await page.reload();await page.getByRole('button',{name:/نَظْرَةٌ عَامَّةٌ/}).waitFor();await click(page,'الدروس');await page.getByRole('button',{name:/تَعْدِيلٌ/}).first().click();await page.getByRole('dialog').waitFor();await page.getByLabel('وصف الدرس',{exact:true}).fill('يجب ألا تُحفظ هذه الجملة عند فشل الشبكة');await page.route('**/api/lessons/speaking/*',r=>r.request().method()==='PUT'?r.fulfill({status:503,contentType:'application/json',body:JSON.stringify({detail:'تعذر الحفظ لاختبار الفشل'})}):r.continue());await page.getByRole('button',{name:'حفظ التغييرات',exact:true}).click();await page.getByText('تعذر الحفظ لاختبار الفشل',{exact:true}).waitFor();assert(await page.getByRole('dialog').isVisible());await page.getByRole('button',{name:'إلغاء',exact:true}).click();await page.getByRole('dialog').waitFor({state:'hidden'});out.push({case:'save HTTP 503 keeps modal open and displays actual error',status:'PASS'});await page.unroute('**/api/lessons/speaking/*');
await fs.writeFile('/private/tmp/sawti-theme-editor-tests.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
